import bpy, json, os
from mathutils import Vector
report={}
for prefix in ['Hut_ThatchedCourse','Hut_RidgeCap','Hut_FrontPanel','Hut_Stilt','Pier_DeckBoard','Pier_Pile','Palm_Frond','Tree_Crown','Boat_Cabin','Boat_Deck']:
    objects=[o for o in bpy.data.objects if o.name.startswith(prefix)]
    report[prefix]={'count':len(objects),'samples':[{'name':o.name,'location':list(o.location),'rotation':list(o.rotation_euler),'scale':list(o.scale),'dimensions':list(o.dimensions),'vertices':len(o.data.vertices),'verts_sample':[list(v.co) for v in list(o.data.vertices)[:4]],'mods':[(m.name,m.type) for m in o.modifiers],'material':[m.name for m in o.data.materials]} for o in objects[:2]]}
print(json.dumps({'pid':os.getpid(),'file':bpy.data.filepath,'report':report}))
